(function(global){
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  const mm=ms=>{const s=Math.max(0,Math.floor(Number(ms||0)/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
  const langClass=code=>`ic-lang-${String(code||'').toLowerCase()}`;
  const phenClass=id=>({'layer-presentation':'ic-phen-presentation','layer-changement-de-langue':'ic-phen-langue','layer-comprehension-collective':'ic-phen-collective','layer-clarification':'ic-phen-clarification','layer-negociation-du-sens':'ic-phen-negociation','layer-mot-piege':'ic-phen-piege','layer-repertoire-plurilingue':'ic-phen-repertoire'}[id]||'ic-phen-presentation');
  function createICTimeline(options){
    const root=options.container;if(!root)throw new Error('IC timeline container missing');
    let activity=options.activity||{},durationMs=Number(options.durationMs||activity.video?.durationMs||1),current=Number(options.currentTime||0),selected=options.selected||null;
    const api={update(data){activity=data.activity||data||activity;durationMs=Number(data.durationMs||activity.video?.durationMs||durationMs);render()},setCurrentTime(ms){current=Number(ms)||0;cursor()},setSelectedElement(s){selected=s||null;render()},destroy(){root.replaceChildren();root.removeEventListener('click',click)}};
    const data=()=>({languages:activity.languages||[],intervals:activity.languageIntervals||[],phenomena:activity.phenomena||[],layers:new Map((activity.layers||[]).map(l=>[l.id,l]))});
    const pct=ms=>Math.max(0,Math.min(100,Number(ms||0)/durationMs*100));
    const bar=(type,x,classes,title)=>`<button type="button" class="${classes}${selected?.id===x.id?' active':''}" data-ic-type="${type}" data-ic-id="${esc(x.id)}" title="${esc(title)}" style="left:${pct(x.startMs)}%;width:${Math.max(pct(x.endMs)-pct(x.startMs),.6)}%"></button>`;
    function render(){const d=data(),ticks=[];for(let t=0;t<=durationMs;t+=60000)ticks.push(t);if(ticks.at(-1)!==durationMs)ticks.push(durationMs);const codes=d.languages.map(l=>l.code||l.label||l.id);const axis=ticks.map(t=>`<span class="ic-time-tick" style="left:${pct(t)}%">${mm(t)}</span>`).join('');const langTracks=codes.map(code=>{const l=d.languages.find(x=>(x.code||x.label||x.id)===code);return d.intervals.filter(x=>x.languageId===l?.id).map(x=>bar('languageInterval',x,`ic-bar ${langClass(code)}`,`${l.label||code} · ${mm(x.startMs)} — ${mm(x.endMs)}`)).join('')});const phenTrack=d.phenomena.map(x=>bar('phenomenon',x,`ic-bar ${phenClass(x.layerId)}`,`${d.layers.get(x.layerId)?.label||'Phénomène'} · ${mm(x.startMs)} — ${mm(x.endMs)}`)).join('');const labels=[...codes,'Phénomènes'].map(label=>`<div class="ic-timeline-label">${esc(label)}</div>`).join('');const legend=[...codes.map(c=>`<span class="ic-legend-item"><i class="ic-legend-swatch ${langClass(c)}"></i>${esc(c)}</span>`),...Array.from(d.layers.values()).map(l=>`<span class="ic-legend-item"><i class="ic-legend-swatch ${phenClass(l.id)}"></i>${esc(l.label||l.id)}</span>`) ].join('');root.innerHTML=`<div class="ic-timeline"><div class="ic-timeline-head"><h2 class="ic-timeline-title">Timeline IC</h2><span class="ic-timeline-scale">${mm(durationMs)}</span></div><div class="ic-timeline-grid"><div class="ic-timeline-label-column">${labels}</div><div class="ic-timeline-plot"><div class="ic-timeline-axis-track">${axis}</div>${langTracks.map(b=>`<div class="ic-track">${b}</div>`).join('')}<div class="ic-track phenomena">${phenTrack}</div><span class="ic-cursor"><span class="ic-cursor-label">${mm(current)}</span></span></div></div><div class="ic-legend">${legend}</div></div>`;cursor()}
    function cursor(){const c=root.querySelector('.ic-cursor');if(c)c.style.left=`${pct(current)}%`;const l=root.querySelector('.ic-cursor-label');if(l)l.textContent=mm(current)}
    function click(e){const hit=e.target.closest('[data-ic-type]');if(hit){const type=hit.dataset.icType,collection=type==='languageInterval'?'languageIntervals':'phenomena',item=(activity[collection]||[]).find(x=>x.id===hit.dataset.icId);if(item){current=item.startMs;const selection=type==='languageInterval'?{type,id:item.id,languageId:item.languageId,startMs:item.startMs,endMs:item.endMs,item}:{type,id:item.id,layerId:item.layerId,startMs:item.startMs,endMs:item.endMs,item};options.onSeek?.(item.startMs,type,item);options.onSelect?.(selection);api.setSelectedElement({id:item.id,type})}return}const axis=e.target.closest('.ic-timeline-axis-track');if(axis){const r=axis.getBoundingClientRect();current=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*durationMs;options.onSeek?.(current,'axis',null);cursor()}}
    root.addEventListener('click',click);render();return api;
  }
  global.createICTimeline=createICTimeline;
})(window);
